def compute(vars):
    volume_weather = vars["v1"]
    ano_decommissioning_trust = vars["v2"]
    retail_electric_price = vars["v3"]
    total_favorable_variance = (
        volume_weather
        + ano_decommissioning_trust
        + retail_electric_price
    )
    return {
        "value": total_favorable_variance,
        "trace": {
            "volume_weather": volume_weather,
            "ano_decommissioning_trust": ano_decommissioning_trust,
            "retail_electric_price": retail_electric_price,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
